//! LZ4 blocks produced by the C library DArc links.
//!
//! Generated by `rust/cryptref/lz4_vectors.cpp`, which calls
//! `LZ4_compress_default` and `LZ4_compress_HC` from `Compression/LZ4` -- the
//! same functions `C_LZ4.cpp` calls.
//!
//! The direction under test is the one that decides whether existing archives
//! open: can this crate decode what the C encoder wrote? The reverse direction
//! is covered separately by a round-trip, since the block format is fixed and
//! a conformant decoder reads any conformant encoder's output.
//!
//! Encoder output is deliberately NOT asserted to match the C library's. LZ4 is
//! a match-finder and encoders differ legitimately; requiring byte-identity
//! would fail for a reason that is not a bug.

use darc_codecs::lz4;

/// (name, original length, C-produced block as hex)
const VECTORS: &[(&str, usize, &str)] = &[
    ("text", 4096, "ff1974686520717569636b2062726f776e20666f78206a756d7073206f766572206c617a7920646f67202800ffffffffffffffffffffffffffffffcf50726f776e20"),
    ("runs", 4096, "1f410100fffffffffffffffffffffffffffffff6504141414141"),
    ("random", 4096, ""),
    ("text-hc", 4096, "ff1974686520717569636b2062726f776e20666f78206a756d7073206f766572206c617a7920646f67202800ffffffffffffffffffffffffffffffcf50726f776e20"),
    ("tiny", 12, "c0616263616263616263616263"),
    ("onebyte", 1, "105a"),
];

fn unhex(s: &str) -> Vec<u8> {
    (0..s.len() / 2)
        .map(|i| u8::from_str_radix(&s[i * 2..i * 2 + 2], 16).unwrap())
        .collect()
}

/// Rebuilds the inputs the C harness compressed, so the decoded bytes can be
/// checked against something rather than merely "decoded without error".
fn original(name: &str, len: usize) -> Vec<u8> {
    match name {
        "text" | "text-hc" => {
            let w = ["the ", "quick ", "brown ", "fox ", "jumps ", "over ", "lazy ", "dog "];
            let mut v = Vec::with_capacity(len);
            let mut i = 0usize;
            loop {
                let s = w[i % 8].as_bytes();
                if v.len() + s.len() > len { break; }
                v.extend_from_slice(s);
                i += 1;
            }
            v.resize(len, b' ');
            v
        }
        "runs" => vec![b'A'; len],
        "random" => {
            let mut s: u32 = 12345;
            (0..len).map(|_| { s = s.wrapping_mul(1103515245).wrapping_add(12345); (s >> 16) as u8 }).collect()
        }
        "tiny" => b"abcabcabcabc".to_vec(),
        "onebyte" => b"Z".to_vec(),
        other => panic!("no reconstruction for vector {other}"),
    }
}

#[test]
fn decodes_blocks_written_by_the_c_library() {
    for &(name, len, hex) in VECTORS {
        let block = unhex(hex);
        let mut out = vec![0u8; len];
        let n = lz4::decompress_block(&block, &mut out)
            .unwrap_or_else(|e| panic!("{name}: decompress_block failed with {e}"));
        assert_eq!(n, len, "{name}: decoded length");
        assert_eq!(out, original(name, len), "{name}: decoded bytes differ from the original");
    }
}

#[test]
fn round_trips_its_own_output() {
    for &(name, len, _) in VECTORS {
        let src = original(name, len);
        let mut packed = vec![0u8; src.len() * 2 + 1024];
        let n = lz4::compress_block(&src, &mut packed)
            .unwrap_or_else(|| panic!("{name}: compress_block declined {} bytes", src.len()));
        packed.truncate(n);

        let mut out = vec![0u8; src.len()];
        let m = lz4::decompress_block(&packed, &mut out).expect("own output rejected");
        assert_eq!(m, src.len());
        assert_eq!(out, src, "{name}: round-trip mismatch");
    }
}

#[test]
fn rejects_corrupt_blocks_without_panicking() {
    // Reachable through "arc t" on a damaged archive. LZ4_decompress_safe is
    // the safe variant precisely because this input is attacker-controlled; a
    // panic unwinding across the C ABI would be undefined behaviour.
    let block = unhex(VECTORS[0].2);
    let len = VECTORS[0].1;
    for cut in [0usize, 1, 2, 5, block.len() / 3, block.len() / 2, block.len() - 1] {
        let mut out = vec![0u8; len];
        drop(lz4::decompress_block(&block[..cut.min(block.len())], &mut out));
    }
    for i in (0..block.len()).step_by(7) {
        let mut bad = block.clone();
        bad[i] ^= 0xff;
        let mut out = vec![0u8; len];
        drop(lz4::decompress_block(&bad, &mut out));
    }
}

#[test]
fn refuses_to_overrun_a_short_output_buffer() {
    // The output capacity is what C_LZ4.cpp passes as BlockSize. A block
    // claiming to expand beyond it must fail, not write past the end.
    let (name, len, hex) = VECTORS[0];
    let block = unhex(hex);
    let mut small = vec![0u8; len / 2];
    assert!(
        lz4::decompress_block(&block, &mut small).is_err(),
        "{name}: decoded into a buffer half the required size"
    );
}
